package com.jadhavr.erp.academic.entity;
import com.jadhavr.erp.academic.enums.AcademicStatus; import com.jadhavr.erp.common.entity.BaseAuditEntity; import com.jadhavr.erp.staff.entity.StaffProfile; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="subject_teacher_assignments") public class SubjectTeacherAssignment extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id",nullable=false) private Subject subject; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="teacher_id",nullable=false) private StaffProfile teacher; @Column(name="academic_year",nullable=false) private String academicYear; @Enumerated(EnumType.STRING) private AcademicStatus status=AcademicStatus.ACTIVE; private LocalDateTime assignedAt=LocalDateTime.now(); public Long getId(){return id;} public Subject getSubject(){return subject;} public void setSubject(Subject v){subject=v;} public StaffProfile getTeacher(){return teacher;} public void setTeacher(StaffProfile v){teacher=v;} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public AcademicStatus getStatus(){return status;} public void setStatus(AcademicStatus v){status=v;} public LocalDateTime getAssignedAt(){return assignedAt;} }
